package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	keyword := r.URL.Query().Get("q")

	// Build base query
	query := "SELECT id, name, price, description FROM products WHERE 1=1"

	// Category filter - parameterized
	args := []interface{}{}
	argIdx := 1

	if category != "" {
		query += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	// Price range - parameterized
	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}
	if maxPrice != "" {
		query += fmt.Sprintf(" AND price <= $%d", argIdx)
		args = append(args, maxPrice)
		argIdx++
	}

	// Keyword search - VULNERABLE: string concatenation
	if keyword != "" {
		// Developer note: using ILIKE for case-insensitive search
		// TODO: switch to full-text search with tsvector
		query += " AND (name ILIKE '%" + keyword + "%' OR description ILIKE '%" + keyword + "%')"
	}

	// Sort - also vulnerable but less obvious
	if sortField != "" {
		allowedSorts := map[string]bool{"price": true, "name": true, "created_at": true}
		if allowedSorts[sortField] {
			query += " ORDER BY " + sortField
		} else {
			query += " ORDER BY created_at DESC"
		}
	} else {
		query += " ORDER BY created_at DESC"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(",\n"))
		}
		// Manual JSON to avoid import
		name = strings.ReplaceAll(name, "\"", "\\\"")
		description = strings.ReplaceAll(description, "\"", "\\\"")
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
		first = false
	}
	w.Write([]byte("\n]"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
